                    'ENGINE': 'django.db.backends.sqlite3',
                    'NAME': ':memory:',
                }
            },
            INSTALLED_APPS=[
                'django.contrib.contenttypes',
                'django.contrib.auth',
            ],
            DEFAULT_AUTO_FIELD='django.db.models.AutoField',
        )
        django.setup()

    from django.db import models, connection

    class TestModel(models.Model):
        our_field = models.JSONField()

        class Meta:
            app_label = 'test_app_in_lookup'

    with connection.schema_editor() as schema_editor:
        schema_editor.create_model(TestModel)

    try:
        # Create test objects
        TestModel.objects.create(our_field={'key': 0})
        TestModel.objects.create(our_field={'key': 1})
        TestModel.objects.create(our_field={'key': 2})

        # Test __in lookup with integer value 0
        first_filter = {'our_field__key__in': [0]}
        first_count = TestModel.objects.filter(**first_filter).count()

        # Test exact lookup for comparison
        second_filter = {'our_field__key': 0}
        second_count = TestModel.objects.filter(**second_filter).count()

        # Both filters should return the same count
        # Oracle patch properly handles JSON extraction for __in lookup
        # Plausible patch uses KeyTransformNumericLookupMixin which doesn't properly
        # wrap RHS params with JSON_EXTRACT on SQLite, causing mismatch
